// Get raw Gemini text
const rawText = $input.item.json.content.parts[0].text;

// Clean any markdown
const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse
let analysis;
try {
  analysis = JSON.parse(cleanedText);
} catch(e) {
  analysis = {
    category:      'General Inquiry',
    urgency:       'Low',
    sentiment:     'Neutral',
    ai_summary:    'Could not parse — manual review needed',
    draft_reply:   'Thank you for contacting us. Our team will review your message and get back to you within 24 hours.',
    internal_note: 'AI parse error — please review this ticket manually'
  };
}

// Pull original email data from Node 2
const emailData = $('Extract and Clean Email Content').item.json;

return {
  json: {
    ticket_id:      emailData.ticket_id,
    message_id:     emailData.message_id,
    thread_id:      emailData.thread_id,
    subject:        emailData.subject,
    sender_email:   emailData.sender_email,
    sender_name:    emailData.sender_name,
    received_at:    emailData.received_at,
    clean_body:     emailData.clean_body,
    category:       analysis.category,
    urgency:        analysis.urgency,
    sentiment:      analysis.sentiment,
    ai_summary:     analysis.ai_summary,
    draft_reply:    analysis.draft_reply,
    internal_note:  analysis.internal_note
  }
};

const email = $input.item.json;

// Extract core email fields
const messageId   = email.id || '';
const threadId    = email.threadId || '';
const subject     = email.subject || '(No Subject)';
const senderFull  = email.from || '';
const receivedAt  = email.date || new Date().toISOString();

// Extract sender email and name
const emailMatch = senderFull.match(/<(.+?)>/);
const nameMatch  = senderFull.match(/^([^<]+)/);
const senderEmail = emailMatch ? emailMatch[1].trim() : senderFull.trim();
const senderName  = nameMatch ? nameMatch[1].trim().replace(/"/g, '') : senderEmail;

// Get email body — n8n Gmail node provides text and/or html
let rawBody = email.text || email.body || email.snippet || '';

// If body is HTML, strip tags
if (rawBody.includes('<')) {
  rawBody = rawBody
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

// Remove quoted reply chains (lines starting with > or On [date] wrote:)
const cleanBody = rawBody
  .split('\n')
  .filter(line => !line.trim().startsWith('>'))
  .filter(line => !line.match(/^On .+ wrote:$/))
  .join('\n')
  .trim()
  .substring(0, 2000); // Cap at 2000 chars — enough for Gemini

// Generate ticket ID
const ticketId = 'TKT-' + Date.now().toString().slice(-6);

return {
  json: {
    ticket_id:    ticketId,
    message_id:   messageId,
    thread_id:    threadId,
    subject:      subject,
    sender_email: senderEmail,
    sender_name:  senderName,
    received_at:  receivedAt,
    clean_body:   cleanBody,
    raw_snippet:  email.snippet || ''
  }
};

