const allTickets = $input.all().map(i => i.json);

// Filter to last 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const weekTickets = allTickets.filter(t => {
  if (!t.received_at) return false;
  return new Date(t.received_at) >= sevenDaysAgo;
});

const total = weekTickets.length;

if (total === 0) {
  return {
    json: {
      summary_email: `Weekly Support Summary\n\nNo support tickets received this week.\n\nHave a great weekend.`,
      subject: `Weekly Support Summary — No Tickets This Week`
    }
  };
}

// Count by category
const byCat = weekTickets.reduce((acc, t) => {
  acc[t.category] = (acc[t.category] || 0) + 1;
  return acc;
}, {});

// Count by urgency
const byUrgency = weekTickets.reduce((acc, t) => {
  acc[t.urgency] = (acc[t.urgency] || 0) + 1;
  return acc;
}, {});

// Count by sentiment
const bySentiment = weekTickets.reduce((acc, t) => {
  acc[t.sentiment] = (acc[t.sentiment] || 0) + 1;
  return acc;
}, {});

// Count actions
const autoReplied  = weekTickets.filter(t => t.auto_reply_sent === 'Yes').length;
const escalated    = weekTickets.filter(t => t.escalated === 'Yes').length;
const routedFin    = weekTickets.filter(t => 
  t.action_taken === 'Routed to finance').length;

// Top issue
const topCategory = Object.entries(byCat)
  .sort((a, b) => b[1] - a[1])[0];

// Format category breakdown
const catBreakdown = Object.entries(byCat)
  .map(([cat, count]) => `  ${cat}: ${count}`)
  .join('\n');

const weekStart = sevenDaysAgo.toISOString().split('T')[0];
const weekEnd   = now.toISOString().split('T')[0];

const summaryEmail = `
WEEKLY SUPPORT SUMMARY
Week of ${weekStart} to ${weekEnd}
================================================

VOLUME
Total tickets received:    ${total}
High urgency escalated:    ${escalated}
Routed to finance:         ${routedFin}
Auto replies sent:         ${autoReplied}

CATEGORY BREAKDOWN
${catBreakdown}

URGENCY BREAKDOWN
  High:    ${byUrgency['High'] || 0}
  Medium:  ${byUrgency['Medium'] || 0}
  Low:     ${byUrgency['Low'] || 0}

SENTIMENT BREAKDOWN
  Angry:      ${bySentiment['Angry'] || 0}
  Frustrated: ${bySentiment['Frustrated'] || 0}
  Neutral:    ${bySentiment['Neutral'] || 0}
  Positive:   ${bySentiment['Positive'] || 0}

TOP ISSUE THIS WEEK
${topCategory ? topCategory[0] + ' (' + topCategory[1] + ' tickets)' : 'N/A'}

================================================
This report was auto-generated by your Customer Support System.
Full ticket log available in your Google Sheet.
`.trim();

return {
  json: {
    summary_email: summaryEmail,
    subject: `Weekly Support Summary — ${total} tickets | ${weekStart} to ${weekEnd}`
  }
};
